from AlgorithmImports import *
from datetime import datetime, timedelta, time


class SpyFiveMinuteCallCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe.IncludeWeeklys()
            .Strikes(-200, 200)
            .Expiration(0, 365)
        )
        self.option_symbol = option.Symbol

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)
        self.previous_fast = None
        self.previous_slow = None
        self.pending_entry_bar = None

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_contract = None
        self.held_expiry = None
        self.entry_fill_price = None
        self.entry_expiries = {}
        self.blocked_entry_date = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

    def OnFiveMinuteBar(self, sender, bar):
        prior_fast = self.fast.Current.Value if self.fast.IsReady else None
        prior_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        bullish_cross = (
            prior_fast is not None
            and prior_slow is not None
            and self.fast.IsReady
            and self.slow.IsReady
            and prior_fast <= prior_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

        self.previous_fast = self.fast.Current.Value if self.fast.IsReady else None
        self.previous_slow = self.slow.Current.Value if self.slow.IsReady else None

        bar_time = bar.EndTime.time()
        if bullish_cross and time(9, 45) <= bar_time <= time(14, 30):
            self.pending_entry_bar = bar.EndTime

    def OnData(self, slice):
        self.HandleUnexpectedEquityPosition()
        self.HandleExpirationRisk()

        if self.held_contract is not None and self.Portfolio[self.held_contract].Quantity > 0:
            self.HandleTimeStop()
            self.HandleProfitTarget(slice)

        if self.pending_entry_bar is not None:
            entry_bar_time = self.pending_entry_bar
            self.pending_entry_bar = None

            if entry_bar_time == self.Time:
                self.TryEnter(slice)

    def TryEnter(self, slice):
        if self.blocked_entry_date == self.Time.date():
            return

        if self.held_contract is not None and self.Portfolio[self.held_contract].Quantity != 0:
            return

        if self.entry_ticket is not None:
            return

        chain = slice.OptionChains.get(self.option_symbol, None)
        if chain is None:
            self.Debug(f"{self.Time}: Entry skipped; no SPY option chain in Slice.")
            return

        spy_price = self.Securities[self.spy].Price
        if spy_price <= 0:
            self.Debug(f"{self.Time}: Entry skipped; SPY price unavailable.")
            return

        eligible = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and (contract.Expiry.date() - self.Time.date()).days >= 7
        ]

        if not eligible:
            self.Debug(f"{self.Time}: Entry skipped; no calls with at least 7 calendar days to expiry.")
            return

        nearest_expiry = min(contract.Expiry.date() for contract in eligible)
        target_strike = spy_price * 1.01

        candidates = [
            contract for contract in eligible
            if contract.Expiry.date() == nearest_expiry
            and contract.Strike >= target_strike
        ]

        if not candidates:
            self.Debug(
                f"{self.Time}: Entry skipped; no call strike at least 1% above SPY "
                f"for expiry {nearest_expiry}."
            )
            return

        selected = min(candidates, key=lambda contract: (contract.Strike, str(contract.Symbol)))
        self.entry_expiries[selected.Symbol] = selected.Expiry.date()
        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)

        self.Debug(
            f"{self.Time}: Entering 1 {selected.Symbol} "
            f"(SPY={spy_price:.2f}, strike={selected.Strike:.2f}, expiry={selected.Expiry.date()})."
        )

    def HandleProfitTarget(self, slice):
        if self.entry_fill_price is None or self.entry_fill_price <= 0:
            return

        quote = slice.QuoteBars.get(self.held_contract, None)
        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2
        if midpoint >= self.entry_fill_price * 1.50:
            self.SubmitExit("profit target")

    def HandleTimeStop(self):
        if self.Time.time() != time(15, 45):
            return

        if self.held_expiry is None:
            return

        if self.Time.date() == self.PreviousTradingDay(self.held_expiry):
            self.SubmitExit("pre-expiration time stop")

    def HandleExpirationRisk(self):
        if self.held_contract is None or self.held_expiry is None:
            return

        if self.Time.date() >= self.held_expiry:
            self.blocked_entry_date = self.Time.date()
            if self.Portfolio[self.held_contract].Quantity != 0:
                self.SubmitExit("expiration safety liquidation")

    def HandleUnexpectedEquityPosition(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            return

        open_orders = self.Transactions.GetOpenOrders(self.spy)
        if not open_orders:
            self.Debug(
                f"{self.Time}: Unexpected SPY equity position from exercise/assignment; liquidating."
            )
            self.MarketOrder(self.spy, -quantity)

    def SubmitExit(self, reason):
        if self.held_contract is None:
            return

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity == 0:
            return

        if self.exit_ticket is not None:
            return

        for order in self.Transactions.GetOpenOrders(self.held_contract):
            if order.Id != (self.entry_ticket.OrderId if self.entry_ticket is not None else -1):
                self.Transactions.CancelOrder(order.Id)

        self.exit_ticket = self.MarketOrder(self.held_contract, -quantity)
        self.Debug(f"{self.Time}: Exiting {self.held_contract} via {reason}.")

    def PreviousTradingDay(self, expiry_date):
        candidate = expiry_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(datetime.combine(candidate, time.min), False):
            candidate -= timedelta(days=1)

        return candidate

    def OnOrderEvent(self, order_event):
        if order_event.Status not in [OrderStatus.Filled, OrderStatus.PartiallyFilled,
                                      OrderStatus.Canceled, OrderStatus.Invalid]:
            return

        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.FillQuantity > 0:
                self.held_contract = order_event.Symbol
                self.held_expiry = self.entry_expiries.get(order_event.Symbol)
                self.entry_fill_price = order_event.FillPrice
                self.Debug(
                    f"{self.Time}: Entry filled {order_event.Symbol} at "
                    f"{order_event.FillPrice:.2f}."
                )

            if order_event.Status in [OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid]:
                self.entry_ticket = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"{self.Time}: Exit filled {order_event.Symbol} at "
                    f"{order_event.FillPrice:.2f}."
                )
                self.held_contract = None
                self.held_expiry = None
                self.entry_fill_price = None
                self.exit_ticket = None
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.exit_ticket = None

