        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            data_normalization_mode=DataNormalizationMode.Raw
        ).Symbol

        self.option_symbol = self.AddOption("SPY", Resolution.Minute).Symbol
        self.OptionFilterUniverse = self.option_symbol
        self.Securities[self.option_symbol].SetFilter(
            lambda universe: universe.Strikes(-100, 100).Expiration(
                timedelta(days=0), timedelta(days=730)
            )
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)
        self.previous_fast = None
        self.previous_slow = None
        self.pending_crossover_bar = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

        self.held_contract = None
        self.held_expiry = None
        self.entry_price = None
        self.entry_order_id = None
        self.exit_order_id = None
        self.expiration_block_date = None
        self.spy_liquidation_order_id = None

    def OnFiveMinuteBar(self, sender, bar):
        prior_fast = self.previous_fast
        prior_slow = self.previous_slow

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if self.fast.IsReady and self.slow.IsReady:
            is_bullish_cross = (
                prior_fast is not None
                and prior_slow is not None
                and prior_fast <= prior_slow
                and self.fast.Current.Value > self.slow.Current.Value
            )

            end_time = bar.EndTime
            eligible_time = (
                (end_time.hour > 9 or (end_time.hour == 9 and end_time.minute >= 45))
                and (end_time.hour < 14 or (end_time.hour == 14 and end_time.minute <= 30))
            )

            if is_bullish_cross and eligible_time:
                self.pending_crossover_bar = end_time

        if self.fast.IsReady:
            self.previous_fast = self.fast.Current.Value
        if self.slow.IsReady:
            self.previous_slow = self.slow.Current.Value

    def OnData(self, data):
        self.HandleUnexpectedSpyPosition()
        self.HandleExpirationProcessing()
        self.HandleExit(data)

        if self.pending_crossover_bar is not None:
            crossover_time = self.pending_crossover_bar
            self.pending_crossover_bar = None

            if crossover_time == self.Time:
                self.TryEnter(data)

    def TryEnter(self, data):
        if self.expiration_block_date == self.Time.date():
            return

        if self.held_contract is not None:
            return

        if self.entry_order_id is not None:
            return

        if self.exit_order_id is not None:
            return

        if self.spy not in data.Bars:
            self.Debug("Skipped entry: no current SPY bar.")
            return

        spy_price = data.Bars[self.spy].Close
        if spy_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)
        candidates = []

        for chain in data.OptionChains.Values:
            for contract in chain:
                if (
                    contract.Right == OptionRight.Call
                    and contract.Expiry.date() >= minimum_expiry
                ):
                    candidates.append(contract)

        if not candidates:
            self.Debug("Skipped entry: no eligible call contracts.")
            return

        nearest_expiry = min(contract.Expiry.date() for contract in candidates)
        minimum_strike = spy_price * 1.01

        eligible = [
            contract for contract in candidates
            if contract.Expiry.date() == nearest_expiry
            and contract.Strike >= minimum_strike
        ]

        if not eligible:
            self.Debug("Skipped entry: no 1% OTM call at nearest expiry.")
            return

        selected = min(eligible, key=lambda contract: (contract.Strike, str(contract.Symbol)))
        ticket = self.MarketOrder(selected.Symbol, 1)

        self.entry_order_id = ticket.OrderId
        self.Debug(
            f"Entry submitted: {selected.Symbol} expiry {selected.Expiry.date()} "
            f"strike {selected.Strike}"
        )

    def HandleExit(self, data):
        if self.held_contract is None:
            return

        if self.exit_order_id is not None:
            return

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity == 0:
            return

        if self.IsPreExpirationTimeStop():
            self.SubmitExit("pre-expiration time stop")
            return

        midpoint = self.GetCurrentOptionMidpoint(data, self.held_contract)
        if (
            midpoint is not None
            and self.entry_price is not None
            and midpoint >= self.entry_price * 1.50
        ):
            self.SubmitExit("50% profit target")

    def GetCurrentOptionMidpoint(self, data, symbol):
        for chain in data.OptionChains.Values:
            for contract in chain:
                if contract.Symbol == symbol:
                    bid = contract.BidPrice
                    ask = contract.AskPrice
                    if bid > 0 and ask > 0:
                        return (bid + ask) / 2.0
                    return None
        return None

    def IsPreExpirationTimeStop(self):
        if self.held_expiry is None:
            return False

        current_date = self.Time.date()
        if current_date >= self.held_expiry:
            return False

        previous_trading_day = self.GetPreviousTradingDay(self.held_expiry)
        if current_date != previous_trading_day:
            return False

        return (self.Time.hour, self.Time.minute) >= (15, 45)

    def GetPreviousTradingDay(self, expiry_date):
        candidate = expiry_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(
            datetime.combine(candidate, datetime.min.time()), False
        ):
            candidate -= timedelta(days=1)

        return candidate

    def HandleExpirationProcessing(self):
        if self.held_contract is None or self.held_expiry is None:
            return

        if self.Time.date() < self.held_expiry:
            return

        self.expiration_block_date = self.Time.date()

        if self.exit_order_id is None and self.Portfolio[self.held_contract].Quantity != 0:
            self.Debug(f"Expiration safeguard exit: {self.held_contract}")
            self.SubmitExit("expiration safeguard")

    def SubmitExit(self, reason):
        if self.held_contract is None:
            return

        for order in self.Transactions.GetOpenOrders(self.held_contract):
            if self.entry_order_id is None or order.Id != self.entry_order_id:
                self.Transactions.CancelOrder(order.Id)

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity == 0:
            return

        ticket = self.MarketOrder(self.held_contract, -quantity)
        self.exit_order_id = ticket.OrderId
        self.Debug(f"Exit submitted ({reason}): {self.held_contract}")

    def HandleUnexpectedSpyPosition(self):
        spy_quantity = self.Portfolio[self.spy].Quantity
        if spy_quantity == 0:
            self.spy_liquidation_order_id = None
            return

        if self.spy_liquidation_order_id is None:
            ticket = self.MarketOrder(self.spy, -spy_quantity)
            self.spy_liquidation_order_id = ticket.OrderId
            self.Debug(
                f"Unexpected SPY exercise/assignment position; liquidating {spy_quantity} shares."
            )

    def OnOrderEvent(self, order_event):
        if (
            self.entry_order_id is not None
            and order_event.OrderId == self.entry_order_id
        ):
            if order_event.Status == OrderStatus.Filled:
                self.held_contract = order_event.Symbol
                self.held_expiry = order_event.Symbol.ID.Date.date()
                self.entry_price = float(order_event.FillPrice)
                self.entry_order_id = None
                self.Debug(
                    f"Entry filled: {self.held_contract} at {self.entry_price:.2f}"
                )
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.Debug(f"Entry order closed without fill: {order_event.Status}")
                self.entry_order_id = None

        if (
            self.exit_order_id is not None
            and order_event.OrderId == self.exit_order_id
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"Exit filled: {order_event.Symbol} at {float(order_event.FillPrice):.2f}"
                )
                self.held_contract = None
                self.held_expiry = None
                self.entry_price = None
                self.exit_order_id = None
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.exit_order_id = None

