from collections import deque
from datetime import datetime, time, timedelta


class SpyFiveMinuteCallCrossover(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        self.spy = self.AddEquity("SPY", Resolution.Minute).Symbol
        self.Securities[self.spy].SetDataNormalizationMode(DataNormalizationMode.Raw)

        option = self.AddOption("SPY", Resolution.Minute)
        self.option_symbol = option.Symbol
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(timedelta(days=0), timedelta(days=365))
        )

        self._closes = deque(maxlen=20)
        self._previous_fast = None
        self._previous_slow = None
        self._pending_bullish_bar = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self._on_five_minute_bar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

        self.held_contract = None
        self.entry_order_id = None
        self.entry_price = None
        self.exit_ticket = None
        self.no_entries_on = set()

    def OnData(self, slice: Slice):
        self._handle_unexpected_spy_position()
        self._handle_expiration(slice)
        self._handle_open_position(slice)
        self._handle_pending_entry(slice)

    def _on_five_minute_bar(self, sender, bar: TradeBar):
        if len(self._closes) == 20:
            self._previous_fast = sum(list(self._closes)[-5:]) / 5.0
            self._previous_slow = sum(self._closes) / 20.0
        else:
            self._previous_fast = None
            self._previous_slow = None

        self._closes.append(bar.Close)

        if len(self._closes) < 20 or self._previous_fast is None:
            return

        fast = sum(list(self._closes)[-5:]) / 5.0
        slow = sum(self._closes) / 20.0

        bullish = self._previous_fast <= self._previous_slow and fast > slow
        bar_time = bar.EndTime.time()

        if bullish and time(9, 45) <= bar_time <= time(14, 30):
            self._pending_bullish_bar = bar.EndTime

    def _handle_pending_entry(self, slice: Slice):
        if self._pending_bullish_bar is None:
            return

        self._pending_bullish_bar = None

        if self.Time.date() in self.no_entries_on:
            return

        if self.held_contract is not None or self._has_open_entry_order():
            return

        if self.Securities[self.spy].Holdings.Quantity != 0:
            return

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug(f"{self.Time}: Entry skipped; SPY option chain unavailable.")
            return

        spy_bar = slice.Bars.get(self.spy)
        spot = spy_bar.Close if spy_bar is not None else self.Securities[self.spy].Price
        if spot <= 0:
            self.Debug(f"{self.Time}: Entry skipped; SPY price unavailable.")
            return

        today = self.Time.date()
        eligible_expiries = sorted(
            {contract.Expiry.date() for contract in chain
             if contract.Right == OptionRight.Call
             and (contract.Expiry.date() - today).days >= 7}
        )

        if not eligible_expiries:
            self.Debug(f"{self.Time}: Entry skipped; no call expiration at least 7 calendar days away.")
            return

        expiry = eligible_expiries[0]
        minimum_strike = spot * 1.01

        candidates = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == expiry
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug(f"{self.Time}: Entry skipped; no qualifying 1% OTM call for {expiry}.")
            return

        selected = min(candidates, key=lambda c: (c.Strike, str(c.Symbol)))
        ticket = self.MarketOrder(selected.Symbol, 1)

        if ticket is not None:
            self.entry_order_id = ticket.OrderId
            self.Debug(
                f"{self.Time}: Entering {selected.Symbol}, expiry {expiry}, "
                f"strike {selected.Strike}."
            )

    def _handle_open_position(self, slice: Slice):
        if self.held_contract is None:
            return

        quantity = self.Securities[self.held_contract].Holdings.Quantity
        if quantity <= 0:
            self.held_contract = None
            self.entry_price = None
            return

        expiry = self.held_contract.ID.Date.date()
        previous_trading_day = self.Securities[self.spy].Exchange.Hours.GetPreviousMarketOpen(
            datetime.combine(expiry, time.min),
            False
        ).date()

        if self.Time.date() == previous_trading_day and self.Time.time() == time(15, 45):
            self._submit_exit("time stop before expiration")
            return

        if self.entry_price is None:
            return

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            return

        contract = next((c for c in chain if c.Symbol == self.held_contract), None)
        if contract is None or contract.BidPrice <= 0 or contract.AskPrice <= 0:
            return

        midpoint = (contract.BidPrice + contract.AskPrice) / 2.0
        if midpoint >= self.entry_price * 1.50:
            self._submit_exit("50% profit target")

    def _handle_expiration(self, slice: Slice):
        if self.held_contract is None:
            return

        expiry = self.held_contract.ID.Date.date()
        if self.Time.date() < expiry:
            return

        self.no_entries_on.add(self.Time.date())

        quantity = self.Securities[self.held_contract].Holdings.Quantity
        if quantity > 0:
            self.Debug(f"{self.Time}: Expiration processing for {self.held_contract}; liquidating.")
            self._submit_exit("expiration processing")

    def _handle_unexpected_spy_position(self):
        quantity = self.Securities[self.spy].Holdings.Quantity
        if quantity == 0:
            return

        self.no_entries_on.add(self.Time.date())
        self.Debug(
            f"{self.Time}: Unexpected SPY position ({quantity}) from exercise/assignment; liquidating."
        )
        self.MarketOrder(self.spy, -quantity)

    def _submit_exit(self, reason: str):
        if self.held_contract is None:
            return

        quantity = self.Securities[self.held_contract].Holdings.Quantity
        if quantity <= 0:
            return

        if self._has_open_exit_order():
            self.exit_ticket.Cancel("Replacing open exit order.")

        self.exit_ticket = self.MarketOrder(self.held_contract, -quantity)
        self.Debug(f"{self.Time}: Exiting {self.held_contract}; {reason}.")

    def _has_open_entry_order(self):
        if self.entry_order_id is None:
            return False

        order = self.Transactions.GetOrderById(self.entry_order_id)
        return order is not None and order.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

    def _has_open_exit_order(self):
        if self.exit_ticket is None:
            return False

        return self.exit_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.OrderId == self.entry_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.held_contract = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.entry_order_id = None
                self.Debug(
                    f"{self.Time}: Entry filled {self.held_contract} at {self.entry_price}."
                )
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.Debug(f"{self.Time}: Entry order {order_event.OrderId} did not fill.")
                self.entry_order_id = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"{self.Time}: Exit filled {order_event.Symbol} at {order_event.FillPrice}."
                )
                self.held_contract = None
                self.entry_price = None
                self.exit_ticket = None

    def OnAssignmentOrderEvent(self, assignment_event: OrderEvent):
        self.no_entries_on.add(self.Time.date())
        self.Debug(f"{self.Time}: Unexpected option assignment/exercise event received.")
        self._handle_unexpected_spy_position()

